export interface TelemetryReading {
  deviceId: string;
  metric: string;
  value: number;
  ts: number;
}

export interface ReadingStore {
  append(readings: TelemetryReading[]): Promise<void>;
}

export interface AlertRule {
  metric: string;
  above?: number;
  below?: number;
}

export interface AlertPublisher {
  publish(alert: { deviceId: string; metric: string; value: number; rule: AlertRule }): Promise<void>;
}

export interface RuleSource {
  rulesFor(deviceId: string): Promise<AlertRule[]>;
}

import { AlertPublisher, AlertRule, RuleSource, TelemetryReading } from "./ports";

export function breaches(rule: AlertRule, value: number): boolean {
  if (rule.above !== undefined && value > rule.above) return true;
  if (rule.below !== undefined && value < rule.below) return true;
  return false;
}

export class ThresholdEvaluator {
  constructor(
    private readonly rules: RuleSource,
    private readonly publisher: AlertPublisher,
  ) {}

  async evaluate(readings: TelemetryReading[]): Promise<number> {
    const byDevice = new Map<string, TelemetryReading[]>();
    for (const r of readings) {
      const list = byDevice.get(r.deviceId) ?? [];
      list.push(r);
      byDevice.set(r.deviceId, list);
    }

    let fired = 0;
    for (const [deviceId, deviceReadings] of byDevice) {
      const rules = await this.rules.rulesFor(deviceId);
      for (const reading of deviceReadings) {
        for (const rule of rules) {
          if (rule.metric === reading.metric && breaches(rule, reading.value)) {
            await this.publisher.publish({ deviceId, metric: reading.metric, value: reading.value, rule });
            fired++;
          }
        }
      }
    }
    return fired;
  }
}

import { ReadingStore, TelemetryReading } from "./ports";
import { ThresholdEvaluator } from "./thresholdEvaluator";

export class InvalidReadingError extends Error {}

export function parseReading(raw: unknown): TelemetryReading {
  const r = raw as Partial<TelemetryReading>;
  if (typeof r?.deviceId !== "string" || r.deviceId.length === 0) {
    throw new InvalidReadingError("deviceId is required");
  }
  if (typeof r.metric !== "string" || typeof r.value !== "number" || !Number.isFinite(r.value)) {
    throw new InvalidReadingError(`bad metric or value for ${r.deviceId}`);
  }
  if (typeof r.ts !== "number") {
    throw new InvalidReadingError(`missing ts for ${r.deviceId}`);
  }
  return { deviceId: r.deviceId, metric: r.metric, value: r.value, ts: r.ts };
}

export class TelemetryIngestService {
  constructor(
    private readonly store: ReadingStore,
    private readonly evaluator: ThresholdEvaluator,
  ) {}

  async ingest(rawBatch: unknown[]): Promise<{ accepted: number; rejected: number; alerts: number }> {
    const accepted: TelemetryReading[] = [];
    let rejected = 0;
    for (const raw of rawBatch) {
      try {
        accepted.push(parseReading(raw));
      } catch (err) {
        if (!(err instanceof InvalidReadingError)) throw err;
        rejected++;
      }
    }
    if (accepted.length === 0) return { accepted: 0, rejected, alerts: 0 };

    await this.store.append(accepted);
    const alerts = await this.evaluator.evaluate(accepted);
    return { accepted: accepted.length, rejected, alerts };
  }
}
